using Microsoft.EntityFrameworkCore;using OrderService.Entities;namespace OrderService.Data;public class OrderDbContext(DbContextOptions<OrderDbContext>o):DbContext(o){public DbSet<Order>Orders=>Set<Order>();public DbSet<OrderItem>OrderItems=>Set<OrderItem>();protected override void OnModelCreating(ModelBuilder m){m.Entity<Order>().ToTable("orders").HasKey(x=>x.OrderId);m.Entity<Order>().Property(x=>x.OrderId).HasColumnName("order_id").HasDefaultValueSql("gen_random_uuid()");m.Entity<Order>().Property(x=>x.UserId).HasColumnName("user_id");m.Entity<Order>().Property(x=>x.OrderStatus).HasColumnName("order_status");m.Entity<Order>().Property(x=>x.CreatedAt).HasColumnName("created_at");m.Entity<Order>().HasMany(x=>x.Items).WithOne(x=>x.Order).HasForeignKey(x=>x.OrderId).OnDelete(DeleteBehavior.Cascade);m.Entity<OrderItem>().ToTable("order_items").HasKey(x=>x.OrderItemId);m.Entity<OrderItem>().Property(x=>x.OrderItemId).HasColumnName("order_item_id").HasDefaultValueSql("gen_random_uuid()");m.Entity<OrderItem>().Property(x=>x.OrderId).HasColumnName("order_id");m.Entity<OrderItem>().Property(x=>x.ProductId).HasColumnName("product_id");m.Entity<OrderItem>().Property(x=>x.Quantity).HasColumnName("quantity");}}